    private UIElement IoPanel(bool full)
    {
        var r=Selected;var body=Ui.Stack();var picker=new ComboBox{ItemsSource=project.Remotes,DisplayMemberPath="Name",SelectedValuePath="Id",SelectedValue=selected};picker.SelectionChanged+=(_,_)=>{if(picker.SelectedValue is int id&&id!=selected){selected=id;Navigate(pageIndex);}};body.Children.Add(picker);body.Children.Add(Ui.Text($"R{selected:00} · {r.Name}",17,null,true));
        var inputs=Ui.Stack(Ui.Text("BEMENETEK",12,Ui.Muted,true));
        for(int i=0;i<(full?8:4);i++){int ch=i;var indicator=Ui.Text("● 0",14,Ui.Muted,true);var label=Ui.Button(r.Inputs[i],()=>RenameSignal(false,ch));label.HorizontalContentAlignment=HorizontalAlignment.Left;label.ToolTip="Jel átnevezése (leállítva)";var state=Ui.Button("Átváltás",()=>{var current=engine.Snapshot().Remotes.First(x=>x.Id==selected);engine.SetInput(selected,ch,!current.Inputs[ch]);});state.ToolTip="Demóbemenet váltása, automatikus szenzorok kikapcsolásával";var row=new DockPanel();DockPanel.SetDock(indicator,Dock.Right);row.Children.Add(indicator);if(full){DockPanel.SetDock(state,Dock.Right);row.Children.Add(state);}var content=Ui.Stack(Ui.Text("DI"+i.ToString("00"),11,Ui.Muted),label);row.Children.Add(content);inputs.Children.Add(row);refreshers.Add(s=>{var value=s.Remotes.First(x=>x.Id==selected).Inputs[ch];indicator.Text=value?"● 1":"○ 0";indicator.Foreground=value?Ui.Green:Ui.Muted;});}
        var outputs=Ui.Stack(Ui.Text("KIMENETEK",12,Ui.Muted,true));for(int i=0;i<4;i++){int ch=i;var toggle=Ui.Button("KI",()=>{var current=engine.Snapshot().Remotes.First(x=>x.Id==selected);engine.SetOutput(selected,ch,!current.Outputs[ch]);},true);toggle.MinWidth=64;var label=Ui.Button(r.Outputs[i],()=>RenameSignal(true,ch));label.ToolTip="Jel átnevezése (leállítva)";label.HorizontalContentAlignment=HorizontalAlignment.Left;var row=new DockPanel();DockPanel.SetDock(toggle,Dock.Right);row.Children.Add(toggle);row.Children.Add(Ui.Stack(Ui.Text("DO"+i.ToString("00"),11,Ui.Muted),label));outputs.Children.Add(row);refreshers.Add(s=>{var remote=s.Remotes.First(x=>x.Id==selected);toggle.Content=remote.Outputs[ch]?"BE":"KI";toggle.Background=remote.Outputs[ch]?Ui.Brush("#078BE1"):Ui.Brush("#20384B");toggle.IsEnabled=s.Running&&!s.SequenceRunning&&remote.Online;});}
        body.Children.Add(full?Ui.Columns(Ui.Card(inputs),Ui.Card(outputs),1):Ui.Stack(inputs,outputs));return body;
