    private void RenameSignal(bool output,int channel){RequireStopped();var list=output?Selected.Outputs:Selected.Inputs;var name=Ui.Prompt(this,"Jel átnevezése",list[channel]);if(name==null)return;StudioProject.CheckName(name,"Jelnév");list[channel]=name;ApplyEdit();Navigate(pageIndex);}
    private UIElement IoMonitor(){var automatic=new CheckBox{Content="Automatikus demószenzorok",IsChecked=engine.AutomaticSensors};automatic.Click+=(_,_)=>engine.AutomaticSensors=automatic.IsChecked==true;return Page("I/O monitor","Jelnévre kattintva átnevezés. A bemenetek demóban kézzel is változtathatók.",Ui.Row(RunControls(),automatic),Ui.Card(IoPanel(true),"Kézi I/O-vezérlés"));}
    private UIElement LogRows(int limit=200)
    {
        var rows=new StackPanel();DateTime last=DateTime.MinValue;
        refreshers.Add(_=>{var all=engine.Logs();var latest=all.FirstOrDefault()?.Time??DateTime.MinValue;if(latest==last)return;last=latest;rows.Children.Clear();var query=all.Where(x=>(logLevel=="Összes"||x.Level==logLevel)&&(x.Message+" "+x.Device).Contains(logSearch,StringComparison.CurrentCultureIgnoreCase)).Take(limit);foreach(var log in query){var line=new Grid{Margin=new Thickness(0,0,0,8)};line.ColumnDefinitions.Add(new(){Width=new GridLength(90)});line.ColumnDefinitions.Add(new(){Width=new GridLength(95)});line.ColumnDefinitions.Add(new(){Width=new GridLength(130)});line.ColumnDefinitions.Add(new(){Width=new GridLength(1,GridUnitType.Star)});string[] parts=[log.Time.ToString("HH:mm:ss"),log.Level,log.Device,log.Message];for(int i=0;i<4;i++){var t=Ui.Text(parts[i],12,i==1&&log.Level!="INFO"?Ui.Amber:Ui.Muted);t.Margin=new Thickness(0,0,12,3);Grid.SetColumn(t,i);line.Children.Add(t);}rows.Children.Add(line);}if(rows.Children.Count==0)rows.Children.Add(Ui.Text("Nincs a szűrőnek megfelelő esemény.",14,Ui.Muted));});return rows;
    }
    private UIElement EventLog(){var search=Ui.Input(logSearch,"Esemény keresése");var levels=new ComboBox{ItemsSource=new[]{"Összes","INFO","FIGYELEM","HIBA"},SelectedItem=logLevel,Width=160};return Page("Eseménynapló","Az utolsó 2 000 esemény; a legutóbbi munkamenet naplója kilépéskor mentésre kerül.",Ui.Card(Ui.Stack(Ui.Columns(search,Ui.Row(levels,Ui.Button("Szűrés",()=>{logSearch=search.Text;logLevel=(string)levels.SelectedItem;Navigate(4);}),Ui.Button("CSV export",ExportLog)),2),LogRows()),"Események"));}
    private void ExportLog(){var dialog=new SaveFileDialog{FileName="SMC-Wireless-naplo.csv",Filter="CSV napló|*.csv"};if(dialog.ShowDialog(this)==true){File.WriteAllText(dialog.FileName,DemoEngine.ExportCsv(engine.Logs()),System.Text.Encoding.UTF8);toast.Text="Napló exportálva.";}}
    private UIElement Projects()
    {
        var saved=Ui.Stack();foreach(var file in store.Files()){try{var p=store.Load(file);saved.Children.Add(Ui.Card(Ui.Stack(Ui.Text(p.Customer,13,Ui.Muted),Ui.Text($"{p.Remotes.Count} remote · {p.Sequences.Count} szekvencia · {p.CycleMs} ms",13,Ui.Muted),Ui.Button("Megnyitás",()=>LoadProject(p))),p.Name));}catch(Exception ex){saved.Children.Add(Ui.Card(Ui.Text(Path.GetFileName(file)+": "+ex.Message,13,Ui.Amber),"Nem olvasható projekt"));}}
        if(saved.Children.Count==0)saved.Children.Add(Ui.Text("Még nincs mentett projekt. A felső Projekt mentése gombbal mentheted az aktuális demót.",15,Ui.Muted));
        var name=Ui.Input(project.Name,"Projektnév");var customer=Ui.Input(project.Customer,"Ügyfél");var detail=Ui.Card(Ui.Stack(Ui.Field("PROJEKTNÉV",name),Ui.Field("ÜGYFÉL",customer),Ui.Button("Adatok mentése",()=>{RequireStopped();StudioProject.CheckName(name.Text,"Projektnév");StudioProject.CheckName(customer.Text,"Ügyfél");project.Name=name.Text.Trim();project.Customer=customer.Text.Trim();ApplyEdit();SaveProject();Navigate(5);},true),Ui.Button("Másolat készítése",()=>{RequireStopped();var clone=project.Clone();clone.Id=Guid.NewGuid();clone.Name=project.Name.Length>88?project.Name[..88]+" – másolat":project.Name+" – másolat";store.Save(clone);Navigate(5);}),Ui.Button("Projekt exportálása",ExportProject),Ui.Text("A projektnevek, jelnevek és lépések megmaradnak verziófrissítéskor is.",13,Ui.Muted),Ui.Button("Projektmappa megnyitása",()=>System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(store.Root){UseShellExecute=true}))),"Aktuális projekt");
        return Page("Projektek","Saját konfigurációk, importálás és biztonsági másolatok.",Ui.Row(Ui.Button("+ Új demóprojekt",()=>{RequireStopped();LoadProject(StudioProject.Demo());MarkDirty();},true),Ui.Button("Projekt importálása",ImportProject)),Ui.Columns(saved,detail,1.5));
    }
    private void LoadProject(StudioProject next){RequireStopped();if(dirty&&MessageBox.Show(this,"Az aktuális módosításokat elveted?","Projekt megnyitása",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;next.Validate();project=next.Clone();engine.ApplyConfig(project);selected=project.Remotes[0].Id;sequenceIndex=stepIndex=0;dirty=false;networkSearch="";onlyFaulty=false;engine.AddLog("INFO","Projekt","Betöltve: "+project.Name);Navigate(0);}
    private void ImportProject(){RequireStopped();var dialog=new OpenFileDialog{Filter="Studio projekt|*.smcws.json;*.json"};if(dialog.ShowDialog(this)!=true)return;var imported=store.Load(dialog.FileName);imported.Id=Guid.NewGuid();LoadProject(imported);if(project.Id==imported.Id){SaveProject();Navigate(5);}}
    private void ExportProject(){var dialog=new SaveFileDialog{FileName="Wireless-projekt.smcws.json",Filter="Studio projekt|*.smcws.json"};if(dialog.ShowDialog(this)==true){store.Export(project,dialog.FileName);toast.Text="Projekt exportálva.";}}
