        var connection=Ui.Card(Ui.Stack(Ui.Field("BASE MEGJELENÍTETT NEVE",baseName),Ui.Field("BASE IPv4-CÍM",ip),Ui.Field("TCP PORT",port),Ui.Button("Beállítások mentése",()=>{RequireStopped();var candidate=project.Clone();candidate.BaseName=baseName.Text.Trim();candidate.BaseIp=ip.Text.Trim();if(!int.TryParse(port.Text,out var n))throw new InvalidDataException("Érvénytelen port.");candidate.Port=n;candidate.Validate();project=candidate;ApplyEdit();SaveProject();Navigate(6);},true),Ui.Text("A címek ebben a kiadásban projektadatok. A demó nem nyit kapcsolatot a base felé.",13,Ui.Muted)),"Kommunikáció");
        var mode=Ui.Card(Ui.Stack(Ui.Badge("DEMÓ · Szimulált I/O"),Ui.Text("Valódi I/O illesztés",18,null,true),Ui.Text("A hardveres kiadáshoz a pontos base-típus, firmware és a dokumentált regisztertérkép szükséges.",14,Ui.Muted),Ui.Text("Itt most az alkalmazás működését, a neveket és a logikát próbálhatod ki valódi kimenetek kapcsolása nélkül.",14,Ui.Muted)),"Működési mód");
