        var updates=Ui.Card(Ui.Stack(Ui.Text("Telepített verzió: "+CurrentVersion.ToString(3),17,null,true),Ui.AsyncButton("Update · Frissítés keresése",CheckUpdates,true),Ui.Text("Az új verziót a projekt GitHub Releases oldaláról töltjük le. Az MSI frissítési útvonala megtartja a projekteket.",13,Ui.Muted),Ui.Button("Kiadások megnyitása",()=>System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("https://github.com/"+ReleaseVersion.Repository+"/releases"){UseShellExecute=true}))),"Frissítések");
        return Page("Beállítások","Kommunikáció, időzítés és verziófrissítések.",Ui.Columns(connection,mode,1),Ui.Columns(timing,updates,1));
